import json
with open('/app/resources/treasury_bulletin_1940_10.json', 'r') as f:
    data = json.load(f)

# Print keys at top level
def print_structure(d, indent=0):
    if isinstance(d, dict):
        for k, v in d.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)) and indent < 2:
                print_structure(v, indent + 2)
    elif isinstance(d, list) and len(d) < 20:
        for i, item in enumerate(d[:5]):
            print(' ' * indent + f'[{i}]')
            if isinstance(item, (dict, list)) and indent < 2:
                print_structure(item, indent + 2)

print_structure(data)
